use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicBool,Ordering};use glam::DVec3;use ingetrazo_core::mesh::Mesh;
static FAIL:AtomicBool=AtomicBool::new(false);struct Fault;unsafe impl GlobalAlloc for Fault{unsafe fn alloc(&self,l:Layout)->*mut u8{if l.size()==3*std::mem::size_of::<Vec<usize>>()&&FAIL.swap(false,Ordering::SeqCst){std::ptr::null_mut()}else{System.alloc(l)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{System.realloc(p,l,n)}}#[global_allocator]static ALLOC:Fault=Fault;
fn triangle(o:&face_owner::FaceOwner)->face_owner::FaceTransaction{let mut t=o.begin().unwrap();t.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).unwrap();t}
fn main(){let mut o=face_owner::FaceOwner::new(Mesh::new()).unwrap();let t=triangle(&o);o.commit(t).unwrap();o.undo().unwrap();let saved=o.mesh().clone();let budget=o.budget();let before=budget.snapshot();let mut earlier=o.begin().unwrap();let candidate=triangle(&o);FAIL.store(true,Ordering::SeqCst);let error=o.commit(candidate).unwrap_err();assert_eq!(error,"New radial records refused");assert!(!FAIL.load(Ordering::SeqCst));assert_eq!(o.mesh(),&saved);assert_eq!(o.history_counts(),(0,1));assert_eq!(budget.snapshot().history,before.history);earlier.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).unwrap();o.commit(earlier).unwrap();assert_eq!(o.history_counts(),(1,0));o.undo().unwrap();o.redo().unwrap();drop(o);assert_eq!(budget.snapshot().total(),0);println!("actual new-radial allocator refusal preserves mesh, Redo, earlier transaction; retry+Undo/Redo and ledger release PASS");}
